"""Consume cloud-generated bytes; local boundary tests do not claim cloud traces."""
import datetime
import unittest
from pathlib import Path
from unittest.mock import patch

from tw import crypto
from tw.cloud_http import SignedRequest, SignedClient, verify_request, request_url
from tw.cloud_wire import load_pinned_json

FIXTURE = Path(__file__).parent / 'fixtures/cloud/6a2d52f7cfcd9be944cb880602007832de637dc0/control/src/enroll/vectors/enrollment-v1.json'
SHA = 'd664576d9f2776e8389d38439bc9c72ed65e758a8201d8eb15f026651bb3fdaa'


def vectors():
    return load_pinned_json(FIXTURE, SHA)['vectors']


def recorded_request(v):
    from urllib.parse import urlencode
    url = 'https://app.titanwarden.com' + v['path'] + '?' + urlencode([tuple(pair) for pair in v['query']])
    h = (('TW-Broker',v['broker_id']),('TW-Date',v['date']),('TW-Nonce',v['nonce']),
         ('TW-Request-Id',v['request_id']),('TW-Sig',v['signature']))
    return SignedRequest(url,v['method'],h,v['body'].encode())


class SignedHTTPTests(unittest.TestCase):
    def test_all_recorded_v4_request_bytes_and_admission(self):
        for v in vectors():
            if v['op'] != 'request':
                continue
            with self.subTest(v['id']):
                message = crypto.request_context(v['org_id'],v['broker_id'],v['method'],v['path'],
                    v['query'],v['request_id'],v['date'],v['nonce'],crypto.sha256(v['body'].encode()).hex())
                self.assertEqual(message.hex(),v['message_hex'])
                self.assertTrue(crypto.p256_verify(crypto.unb64url(v['public_key']),message,crypto.unb64url(v['signature'])))
                req = recorded_request(v)
                if v['admission'] == 'accept':
                    self.assertEqual(verify_request(req,v['org_id'],v['broker_id'],crypto.unb64url(v['public_key']),v['date']),message)
                else:
                    with self.assertRaises(ValueError):
                        verify_request(req,v['org_id'],v['broker_id'],crypto.unb64url(v['public_key']),v['date'])
                self.assertEqual(crypto.unb64url(req.forwarding()['body_b64']),req.body)

    def test_local_inclusive_date_window(self):
        v = next(v for v in vectors() if v['id']=='review-canonical-request')
        base = datetime.datetime.fromisoformat(v['date'])
        for skew in (-300001,-300000,300000,300001):
            now = (base+datetime.timedelta(milliseconds=skew)).isoformat(timespec='milliseconds').replace('+00:00','Z')
            with self.subTest(skew=skew):
                if abs(skew)==300000:
                    verify_request(recorded_request(v),v['org_id'],v['broker_id'],crypto.unb64url(v['public_key']),now)
                else:
                    with self.assertRaises(ValueError):
                        verify_request(recorded_request(v),v['org_id'],v['broker_id'],crypto.unb64url(v['public_key']),now)

    def test_prepare_empty_post_get_and_explicit_retry(self):
        v = next(v for v in vectors() if v['id']=='review-canonical-request')
        sent=[]
        client = SignedClient(v['org_id'],v['broker_id'],crypto.generate_p256_key(),clock=lambda:v['date'],transport=lambda r: sent.append(r))
        url='https://app.titanwarden.com'+v['path']
        first=client.prepare('POST',url)
        retry=client.prepare('POST',url,logical_id=dict(first.headers)['TW-Request-Id'])
        self.assertEqual(first.body,b'{}')
        self.assertNotEqual(dict(first.headers)['TW-Nonce'],dict(retry.headers)['TW-Nonce'])
        with self.assertRaises(ValueError):
            client.prepare('POST',url,{'changed':True},logical_id=dict(first.headers)['TW-Request-Id'])
        client.send_once(first)
        self.assertEqual(sent,[first])
        get=client.prepare('GET',url)
        self.assertEqual(get.body,b'')
        self.assertNotIn('body_b64',get.forwarding())
        with self.assertRaises(ValueError):
            client.prepare('GET',url,{})
        with self.assertRaises(ValueError):
            client.prepare('POST',url,logical_id='-')

    def test_ambiguous_transport_is_not_retried(self):
        v=next(v for v in vectors() if v['id']=='review-canonical-request')
        calls=[]
        def fail(r):
            calls.append(r)
            raise TimeoutError('lost response')
        client=SignedClient(v['org_id'],v['broker_id'],crypto.generate_p256_key(),clock=lambda:v['date'],transport=fail)
        with self.assertRaises(TimeoutError):
            client.send_once(client.prepare('POST','https://app.titanwarden.com'+v['path']))
        self.assertEqual(len(calls),1)

    def test_encoded_alias_and_url_rewrites_refuse(self):
        org='a'*32
        for suffix in ('?a=1&%61=2','?a=1&a=2','/../sync/head','/%2e%2e/sync/head','?a=%xx','#fragment'):
            with self.subTest(suffix=suffix),self.assertRaises(ValueError):
                request_url('https://app.titanwarden.com/v1/orgs/'+org+'/sync/head'+suffix,org)

    def test_node_whatwg_pathnames_are_used_for_signing_and_local_verification(self):
        data=load_pinned_json(Path(__file__).parent/'fixtures/whatwg-pathnames-node.json',
            'b4d08b4b7eecfe12de361a502755ec0472369c1f930b207698bf727e3dae78d9')
        org='a'*32
        client=SignedClient(org,'brk_'+'a'*32,crypto.generate_p256_key(),clock=lambda:'2027-01-15T08:00:00.000Z')
        public=crypto.export_point(client._signing_key.public_key())
        for case in data['cases']:
            with self.subTest(url=case['url']):
                path,query=request_url(case['url'],org)
                self.assertEqual(path,case['pathname'])
                # A pipe is a context delimiter and is refused by both core
                # implementations even though WHATWG leaves it in a pathname.
                if '|' in path:
                    with self.assertRaises(ValueError): client.prepare('GET',case['url'])
                    continue
                request=client.prepare('GET',case['url'])
                message=verify_request(request,org,client.broker,public,client._clock())
                h=dict(request.headers)
                self.assertEqual(message,crypto.request_context(org,client.broker,'GET',case['pathname'],query,
                    h['TW-Request-Id'],h['TW-Date'],h['TW-Nonce'],crypto.sha256(b'').hex()))

    def test_signature_nonce_and_each_header_gate_has_a_negative(self):
        from dataclasses import replace
        org='a'*32
        client=SignedClient(org,'brk_'+'a'*32,crypto.generate_p256_key(),clock=lambda:'2027-01-15T08:00:00.000Z')
        original=client.prepare('POST','https://api.titanwarden.com/v1/orgs/'+org+'/sync/head')
        public=crypto.export_point(client._signing_key.public_key())
        signature=bytearray(crypto.unb64url(dict(original.headers)['TW-Sig']));signature[0]^=1
        changed=dict(original.headers,**{'TW-Sig':crypto.b64url(bytes(signature))})
        with self.assertRaisesRegex(ValueError,'request signature differs'):
            verify_request(replace(original,headers=tuple(changed.items())),org,client.broker,public,client._clock())
        for headers in (original.headers+(('Cookie','untrusted'),),original.headers+(original.headers[0],),
                        tuple((k,'brk_other' if k=='TW-Broker' else v) for k,v in original.headers),
                        tuple((k,v) for k,v in original.headers if k!='TW-Sig'),
                        tuple(('Cookie' if k=='TW-Sig' else k,v) for k,v in original.headers)):
            with self.subTest(headers=headers),self.assertRaisesRegex(ValueError,'exact five TW headers'):
                verify_request(replace(original,headers=headers),org,client.broker,public,client._clock())
        # Re-sign a short nonce so failure cannot be attributed to the signature.
        changed=dict(original.headers);changed['TW-Nonce']=crypto.b64url(b'abc')
        message=crypto.request_context(org,client.broker,'POST',request_url(original.url,org)[0],[],
            changed['TW-Request-Id'],changed['TW-Date'],changed['TW-Nonce'],crypto.sha256(original.body).hex())
        changed['TW-Sig']=crypto.b64url(crypto.p256_sign(client._signing_key,message))
        with self.assertRaisesRegex(ValueError,'nonce must contain 16 bytes'):
            verify_request(replace(original,headers=tuple(changed.items())),org,client.broker,public,client._clock())

    def test_send_once_checks_signature_before_transport_effect(self):
        from dataclasses import replace
        client=SignedClient('a'*32,'brk_'+'a'*32,crypto.generate_p256_key(),clock=lambda:'2027-01-15T08:00:00.000Z',transport=lambda r: effects.append(r))
        effects=[]
        original=client.prepare('POST','https://api.titanwarden.com/v1/orgs/'+'a'*32+'/sync/head')
        with self.assertRaisesRegex(ValueError,'request signature differs'):
            client.send_once(replace(original,body=b'{"altered":true}'))
        self.assertEqual(effects,[])
